import React from 'react';
import { useAuth } from '../context/AuthContext';
import NotificationBell from '../Notifications/NotificationBell';
import ChatIcon from '../Chat/ChatIcon';

const Navbar = () => {
  const { user, logout } = useAuth();

  return (
    <nav className="bg-white/95 border-b border-slate-200 px-6 py-4 flex flex-wrap items-center justify-between gap-4 sticky top-0 z-30 shadow-sm backdrop-blur-xl">
      <div className="flex items-center gap-4">
        <div className="w-10 h-10 rounded-2xl bg-blue-100 text-blue-700 grid place-items-center font-bold shadow-sm">
          S
        </div>
        <div>
          <h1 className="text-xl font-semibold tracking-tight text-slate-900">SOTACIB Workflow</h1>
          <p className="text-sm text-slate-500">Gestion intelligente des demandes et des utilisateurs</p>
        </div>
      </div>
      <div className="flex items-center gap-4">
        <NotificationBell />
        <ChatIcon />
        <div className="rounded-2xl border border-slate-200 bg-slate-50 px-3 py-2 text-sm text-slate-700 shadow-sm">
          {user?.fullName}
          <span className="ml-2 px-2 py-0.5 rounded-full bg-blue-50 text-blue-700 text-xs font-semibold">{user?.role}</span>
        </div>
        <button onClick={logout} className="btn btn-danger text-sm">Déconnexion</button>
      </div>
    </nav>
  );
};

export default Navbar;
